<?php require_once 'includes/bootstrap.php'; require_login(); if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){flash('error','Invalid request.');redirect('courses.php');}$course=(int)($_POST['course_id']??0);$s=db()->prepare('SELECT id FROM courses WHERE id=? AND is_active=1');$s->execute([$course]);if(!$s->fetch()){flash('error','Course not found.');redirect('courses.php');}$s=db()->prepare('SELECT id FROM enrollments WHERE user_id=? AND course_id=?');$s->execute([current_user()['id'],$course]);if(!$s->fetch()){$s=db()->prepare('INSERT INTO enrollments(user_id,course_id) VALUES(?,?)');$s->execute([current_user()['id'],$course]);$u=db()->prepare("UPDATE users SET role='member' WHERE id=? AND role='normal'");$u->execute([current_user()['id']]);$_SESSION['user']['role']='member';flash('success','Course enrolment completed.');}else{flash('success','You are already enrolled.');}redirect('course.php?id='.$course); ?>